// Build the ElevenLabs knowledge-base documents from the portfolio's source of truth.
//
// Reads src/data/{projects,experience,skills}.ts and emits one focused, accurate
// markdown document per project, plus a project index, a chronological timeline, an
// experience doc, and a skills doc into elevenlabs/knowledge-base/. These files are
// GENERATED — do not edit them by hand. Edit the source data files and re-run
// `npm run kb:build`.
//
// The hand-written curated docs (00-start-here, 01-profile, 02-education, 05-faq,
// 06-portfolio-site) are NEVER touched by this script.
//
// Run: npm run kb:build   (node --experimental-strip-types scripts/build-elevenlabs-kb.mjs)

import { writeFileSync, mkdirSync, readdirSync, rmSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { projects } from "../src/data/projects.ts";
import { experiences } from "../src/data/experience.ts";
import { skillGroups } from "../src/data/skills.ts";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const KB = join(ROOT, "elevenlabs", "knowledge-base");
const PROJECTS_DIR = join(KB, "projects");

const SITE = "https://azizu.dev";

const GENERATED_BANNER =
  "<!-- GENERATED by scripts/build-elevenlabs-kb.mjs — do not edit by hand. Edit src/data/*.ts and run `npm run kb:build`. -->";

// --- date normalization -----------------------------------------------------
// The website's `date` field is a display string ("June 2026", "Hacklytics 2026").
// We normalize it to a sortable (year, month) so recency questions are answerable.

const MONTHS = {
  january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
  july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
};

// Display strings that aren't "Month YYYY" need an explicit mapping (confirmed dates).
const DATE_OVERRIDES = {
  "Hacklytics 2026": { y: 2026, m: 2, display: "February 2026 (Hacklytics 2026)" },
};

function parseDate(dateStr) {
  if (DATE_OVERRIDES[dateStr]) return DATE_OVERRIDES[dateStr];
  const m = dateStr.match(/^([A-Za-z]+)\s+(\d{4})$/);
  if (m && MONTHS[m[1].toLowerCase()]) {
    return { y: Number(m[2]), m: MONTHS[m[1].toLowerCase()], display: dateStr };
  }
  return { y: 0, m: 0, display: dateStr }; // unknown sorts oldest
}

const sortKey = (p) => {
  const d = parseDate(p.date);
  return d.y * 100 + d.m;
};

// --- small text helpers -----------------------------------------------------

function article(word) {
  return /^[aeiou]/i.test(word) ? "an" : "a";
}

function humanList(items) {
  if (!items || items.length === 0) return "";
  if (items.length === 1) return items[0];
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(", ")}, and ${items[items.length - 1]}`;
}

function slugify(title) {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

const uniq = (arr) => [...new Set(arr)];

// --- technology classification (drives accurate, answer-shaped Q&A) ---------

const DB_NAMES = ["postgresql", "supabase", "firebase", "mongodb", "mysql", "sqlite", "redis", "upstash redis"];
const VECTOR_NAMES = ["pgvector", "pinecone", "weaviate", "qdrant", "chroma", "milvus"];
const AI_NAMES = [
  "openai", "google gemini", "gemini", "hugging face", "ollama", "langchain",
  "pytorch", "vercel ai sdk", "openai whisper", "whisper", "claude",
];

const has = (techs, names) => techs.filter((t) => names.includes(t.toLowerCase()));

function vectorDbAnswer(techs) {
  const found = has(techs, VECTOR_NAMES);
  if (!found.length) return null;
  if (found.some((t) => t.toLowerCase() === "pgvector")) {
    const onSupabase = techs.some((t) => t.toLowerCase() === "supabase");
    return onSupabase
      ? "Supabase with the pgvector extension"
      : "PostgreSQL with the pgvector extension";
  }
  return humanList(found);
}

// --- project document -------------------------------------------------------

function renderProject(p) {
  const d = parseDate(p.date);
  const lines = [];
  lines.push(GENERATED_BANNER, "");
  lines.push(`# ${p.title}`, "");
  lines.push(
    `${p.title} is one of my (Aziz Umarov's) ${p.category} projects, built ${d.display}.` +
      (p.award ? ` It won ${p.award}.` : ""),
    "",
  );

  // Self-identifying summary so retrieved chunks always name the project.
  const descLower = /^[A-Z][a-z]/.test(p.description)
    ? `${p.description.charAt(0).toLowerCase()}${p.description.slice(1)}`
    : p.description;
  const descArticle = article(descLower.split(/\s+/)[0]);
  lines.push("## Summary");
  lines.push(`${p.title} is ${descArticle} ${descLower}`, "");

  if (p.details) {
    lines.push("## What it is");
    lines.push(p.details, "");
  }

  if (p.keyFeatures && p.keyFeatures.length) {
    lines.push("## Key features");
    for (const f of p.keyFeatures) lines.push(`- ${f}`);
    lines.push("");
  }

  lines.push("## Tech stack");
  lines.push(`${p.title} is built with ${humanList(p.technologies)}.`, "");

  lines.push("## Quick facts");
  lines.push(`- Project: ${p.title}`);
  lines.push(`- Type: ${p.category}`);
  lines.push(`- Built: ${d.display}`);
  if (p.award) lines.push(`- Award: ${p.award}`);
  if (p.liveHref) lines.push(`- Live demo: ${p.liveHref}`);
  if (p.githubHref) lines.push(`- Source code: ${p.githubHref}`);
  lines.push("");

  // Derived, accurate Q&A that mirrors how visitors actually phrase questions.
  const dbs = has(p.technologies, DB_NAMES);
  const vec = vectorDbAnswer(p.technologies);
  const ais = has(p.technologies, AI_NAMES);
  lines.push(`## Common questions about ${p.title}`);
  lines.push(`- When did I build ${p.title}? ${d.display}.`);
  lines.push(`- What is ${p.title} built with? ${humanList(p.technologies)}.`);
  if (dbs.length) lines.push(`- What database does ${p.title} use? ${humanList(dbs)}.`);
  if (vec) lines.push(`- What vector database or vector store does ${p.title} use? ${vec}.`);
  if (ais.length) lines.push(`- What AI, LLM, or ML does ${p.title} use? ${humanList(ais)}.`);
  if (p.award) lines.push(`- Did ${p.title} win anything? Yes — ${p.award}.`);
  lines.push("");

  lines.push("## How I talk about this project");
  lines.push(
    `If someone asks me about ${p.title}, I'd tell them it's ${descArticle} ${descLower} ` +
      `I built it with ${humanList(p.technologies.slice(0, 4))}.` +
      (p.award ? ` It won ${p.award}.` : "") +
      (p.liveHref ? ` I can point them to the live demo at ${p.liveHref}` : "") +
      (p.githubHref ? ` and the source on my GitHub at ${p.githubHref}.` : "."),
    "",
  );

  // Keyword/synonym expansion to widen retrieval recall on paraphrased queries.
  const kw = [p.title, p.category, ...p.technologies];
  if (vec) kw.push("vector database", "vector store", "vector search", "semantic search", "embeddings");
  if (dbs.length) kw.push("database", "storage", "backend");
  if (ais.length) kw.push("AI", "LLM", "artificial intelligence", "machine learning");
  lines.push(`Keywords: ${uniq(kw).join(", ")}.`, "");

  return lines.join("\n");
}

// --- timeline doc (always-in-prompt; makes recency questions answerable) -----

function renderTimeline() {
  const sorted = [...projects].sort((a, b) => sortKey(b) - sortKey(a));
  const newestKey = sortKey(sorted[0]);
  const newest = sorted.filter((p) => sortKey(p) === newestKey);
  const newestNames = humanList(newest.map((p) => p.title));
  const newestDate = parseDate(sorted[0].date).display;

  const lines = [];
  lines.push(GENERATED_BANNER, "");
  lines.push("# Projects timeline (most recent first)", "");
  lines.push(
    "My projects ordered newest to oldest, so I can answer questions about my most recent, latest, " +
      "newest, or oldest work accurately and never default to a well-known project by mistake.",
    "",
  );
  lines.push(
    `My most recent project${newest.length > 1 ? "s are" : " is"} ${newestNames} (${newestDate}). ` +
      "My award-winning CrisisLens is from February 2026, which is NOT my most recent work.",
    "",
  );

  lines.push("## Newest to oldest");
  sorted.forEach((p, i) => {
    const d = parseDate(p.date);
    lines.push(
      `${i + 1}. ${p.title} — ${d.display} — ${p.category}${p.award ? ` — ${p.award}` : ""}`,
    );
  });
  lines.push("");

  lines.push("## Answering recency questions");
  lines.push(
    `If someone asks for my most recent, latest, or newest project, the answer is ${newestNames} ` +
      `(${newestDate}) — not CrisisLens (February 2026), which is older but won an award. ` +
      `My oldest projects are from September 2025 (${humanList(
        sorted.slice(-3).map((p) => p.title),
      )}). I should compare the dates above rather than guessing.`,
    "",
  );
  return lines.join("\n");
}

// --- project index ----------------------------------------------------------

function renderProjectIndex() {
  const byCategory = new Map();
  for (const p of projects) {
    if (!byCategory.has(p.category)) byCategory.set(p.category, []);
    byCategory.get(p.category).push(p);
  }
  const sorted = [...projects].sort((a, b) => sortKey(b) - sortKey(a));

  const lines = [];
  lines.push(GENERATED_BANNER, "");
  lines.push("# Projects index", "");
  lines.push(
    `I (Aziz Umarov) have ${projects.length} projects on my portfolio, spanning AI products, full-stack web apps, ` +
      `React apps, games, and front-end fundamentals. This index helps find the right project; each project also ` +
      `has its own document with more detail. Live demos are on my portfolio at ${SITE}/projects. ` +
      `For "most recent / latest" questions, use the order below (newest first).`,
    "",
  );

  lines.push("## Most recent first");
  sorted.forEach((p) => {
    lines.push(`- ${p.title} (${parseDate(p.date).display})${p.award ? ` — ${p.award}` : ""}`);
  });
  lines.push("");

  const flagship = projects.filter((p) => p.award || p.category === "AI product");
  if (flagship.length) {
    lines.push("## Flagship and award-winning projects");
    for (const p of flagship) {
      lines.push(`- ${p.title}${p.award ? ` (${p.award})` : ""}: ${p.description}`);
    }
    lines.push("");
  }

  lines.push("## All projects by category");
  for (const [category, items] of byCategory) {
    lines.push(`### ${category}`);
    for (const p of items) {
      const live = p.liveHref ? ` — live: ${p.liveHref}` : "";
      lines.push(`- ${p.title} (${parseDate(p.date).display}): ${p.description}${live}`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

// --- experience + skills ----------------------------------------------------

function renderExperience() {
  const lines = [];
  lines.push(GENERATED_BANNER, "");
  lines.push("# Experience", "");
  lines.push(
    "My (Aziz Umarov's) professional and research experience. I'm an early-career software engineer and UCF " +
      "computer science student, currently balancing an industry developer role with undergraduate AI research.",
    "",
  );
  for (const e of experiences) {
    lines.push(`## ${e.role} — ${e.company}`);
    lines.push(`- Period: ${e.period}`);
    lines.push(`- Location: ${e.location}`);
    lines.push(`- Technologies: ${humanList(e.technologies)}.`, "");
    lines.push(e.summary, "");
  }
  lines.push("## How I talk about my experience");
  lines.push(
    "When someone asks what I do or where I work, I lead with my Knight Hacks software developer role " +
      "and my ISUE Lab research on AI speech-therapy feedback, then offer to go deeper on either one.",
    "",
  );
  return lines.join("\n");
}

function renderSkills() {
  const lines = [];
  lines.push(GENERATED_BANNER, "");
  lines.push("# Skills", "");
  lines.push(
    "My (Aziz Umarov's) technical skills, grouped by area. These are interview-defensible skills I actually use " +
      "across my projects, research, and Knight Hacks work — not an aspirational list.",
    "",
  );
  for (const g of skillGroups) {
    lines.push(`## ${g.title}`);
    lines.push(humanList(g.skills) + ".", "");
  }
  lines.push("## How I talk about my skills");
  lines.push(
    "My strongest throughline is full-stack TypeScript, React, and Next.js plus practical AI engineering " +
      "(OpenAI, RAG, embeddings, PyTorch). I also have real cloud and DevOps exposure (AWS, Docker, Kubernetes, CI/CD). " +
      "If someone asks what I'm best at, I emphasize full-stack web plus applied AI, and point to CrisisLens, PopChoice, " +
      "and my ISUE Lab research as proof.",
    "",
  );
  return lines.join("\n");
}

// --- write everything -------------------------------------------------------

mkdirSync(PROJECTS_DIR, { recursive: true });
if (existsSync(PROJECTS_DIR)) {
  for (const f of readdirSync(PROJECTS_DIR)) {
    if (f.endsWith(".md")) rmSync(join(PROJECTS_DIR, f));
  }
}

let smallest = Infinity;
let smallestName = "";
for (const p of projects) {
  const content = renderProject(p);
  const bytes = Buffer.byteLength(content, "utf8");
  if (bytes < smallest) {
    smallest = bytes;
    smallestName = p.title;
  }
  if (bytes < 500) {
    console.warn(`  ⚠ ${p.title} is ${bytes} bytes (< 500) and will NOT be RAG-indexed.`);
  }
  writeFileSync(join(PROJECTS_DIR, `${slugify(p.title)}.md`), content, "utf8");
}

writeFileSync(join(PROJECTS_DIR, "index.md"), renderProjectIndex(), "utf8");
writeFileSync(join(KB, "03-experience.md"), renderExperience(), "utf8");
writeFileSync(join(KB, "04-skills.md"), renderSkills(), "utf8");
writeFileSync(join(KB, "07-timeline.md"), renderTimeline(), "utf8");

console.log(`✓ Wrote ${projects.length} project docs + index, timeline, experience, skills`);
console.log(`✓ Output: ${KB}`);
console.log(
  `✓ Smallest project doc: "${smallestName}" at ${smallest} bytes ` +
    `(${smallest >= 500 ? "all clear" : "SOME DOCS TOO SMALL"})`,
);
